home+='<div class="usp"><div class="container">'+''.join(f'<div><span aria-hidden="true">{ic}</span>{t}</div>' for ic,t in [('◷','24/7 ACCESS'),('▥','8 RACKS'),('⊢⊣','SPECIALTY BARS'),('↟','POWERLIFTING'),('◎','WEIGHTLIFTING')])+'</div></div>'
home+=section('<div class="about" id="about"><div class="about-photo">'+pic(1)+'<span>REAL EQUIPMENT. REAL TRAINING.</span></div><div><p class="eyebrow">ABOUT STATE LINE GYM</p><h2>YOUR GOALS.<br>YOUR HOURS. YOUR GYM.</h2><p>We built State Line Gym around the work you come here to do: squat, press, pull and get stronger. Our open-air warehouse in Southeast Austin gives you the equipment and 24/7 member access to make training part of your life.</p><div class="features">'+''.join(f'<div><h3>{t}</h3><p>{d}</p></div>' for t,d in [('24/7 ACCESS','Get your session in before work, after hours or on the weekend.'),('BUILT FOR STRENGTH','A space for powerlifting, weightlifting and consistent strength work.'),('QUALITY EQUIPMENT','Eight racks, specialty bars, dumbbells and machines.'),('INDEPENDENT GYM','Talk directly with Tom about joining, visiting or getting started.')])+'</div></div></div>')
home+=section(heading('MEMBERSHIPS','SIMPLE PRICING.<br>24/7 ACCESS.','Here for a week or building a long-term routine? Choose from five membership lengths, all with 24/7 access. Visiting Austin? Start with a $13 day pass.')+prices(),'pricing-section')
